package com.javacodingagent.bootstrap.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
public class JwtService { private final SecretKey key; public JwtService(String configured) { byte[] bytes = configured == null || configured.isBlank() ? random() : configured.getBytes(StandardCharsets.UTF_8); if (bytes.length < 32) throw new IllegalArgumentException("JWT_SECRET must contain at least 32 bytes"); key = Keys.hmacShaKeyFor(bytes); } public String issue(String subject) { Instant now = Instant.now(); return Jwts.builder().subject(subject).issuedAt(Date.from(now)).expiration(Date.from(now.plus(Duration.ofHours(8)))).signWith(key).compact(); } public String verify(String token) { return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject(); } private byte[] random() { byte[] value = new byte[32]; new java.security.SecureRandom().nextBytes(value); return value; } }
